arguments.command:
mkdir -p /workspace/submission/infra && cd /workspace/submission/infra
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.60.0"
    }
  }
}
EOF
cat > main.tf <<'EOF'
variable "config_file" {
  description = "Path to the deployment inputs"
  type        = string
  default     = "/workspace/config/config.json"
}

locals {
  cfg      = jsondecode(file(var.config_file))
  prefix   = local.cfg.resource_prefix
  region   = local.cfg.region
  endpoint = local.cfg.aws_endpoint_url

  tags = {
    ClearLedgerDeployment = local.prefix
  }

  azs = ["${local.region}a", "${local.region}b"]

  api_log_group_name       = "/clearledger/${local.prefix}/api"
  projector_log_group_name = "/clearledger/${local.prefix}/projector"
  relay_log_group_name     = "/clearledger/${local.prefix}/outbox-relay"
  archiver_log_group_name  = "/clearledger/${local.prefix}/audit-archiver"

  database_url = "postgres://${local.cfg.db_username}:${local.cfg.db_password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${local.cfg.db_name}"
  valkey_url   = "redis://${aws_elasticache_replication_group.valkey.primary_endpoint_address}:6379"

  # Credentials/region injected explicitly: the workers talk to the local control plane.
  base_env = {
    AWS_REGION            = local.region
    AWS_DEFAULT_REGION    = local.region
    AWS_ACCESS_KEY_ID     = "test"
    AWS_SECRET_ACCESS_KEY = "test"
    AWS_ENDPOINT_URL      = local.endpoint
  }
}

provider "aws" {
  region                      = local.region
  access_key                  = "test"
  secret_key                  = "test"
  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = true
  skip_region_validation      = true
  s3_use_path_style           = true

  endpoints {
    ec2            = local.endpoint
    elbv2          = local.endpoint
    ecs            = local.endpoint
    rds            = local.endpoint
    elasticache    = local.endpoint
    dynamodb       = local.endpoint
    s3             = local.endpoint
    sqs            = local.endpoint
    lambda         = local.endpoint
    scheduler      = local.endpoint
    cognitoidp     = local.endpoint
    iam            = local.endpoint
    kms            = local.endpoint
    cloudwatchlogs = local.endpoint
    sts            = local.endpoint
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}
EOF
cat > vpc.tf <<'EOF'
locals {
  vpc_cidr             = "10.60.0.0/16"
  public_subnet_cidrs  = ["10.60.0.0/24", "10.60.1.0/24"]
  private_subnet_cidrs = ["10.60.10.0/24", "10.60.11.0/24"]
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.tags, { Name = "${local.prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.prefix}-igw" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true
  tags                    = merge(local.tags, { Name = "${local.prefix}-public-${count.index + 1}", Tier = "public" })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags                    = merge(local.tags, { Name = "${local.prefix}-private-${count.index + 1}", Tier = "private" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.prefix}-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.prefix}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# --- Security groups (rules are inline so Terraform owns them exclusively) ---

resource "aws_security_group" "alb" {
  name        = "${local.prefix}-alb"
  description = "ClearLedger ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Egress to the ECS tasks only (VPC CIDR avoids a SG<->SG dependency cycle).
  egress {
    description = "To ECS tasks"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-alb" })
}

resource "aws_security_group" "ecs" {
  name        = "${local.prefix}-ecs"
  description = "ClearLedger API tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "API port from ALB only"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "AWS control plane (HTTPS)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "AWS control plane (local endpoint)"
    from_port   = 4566
    to_port     = 4566
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "PostgreSQL"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Valkey"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-ecs" })
}

resource "aws_security_group" "rds" {
  name        = "${local.prefix}-rds"
  description = "ClearLedger PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from ECS"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.prefix}-rds" })
}

resource "aws_security_group" "valkey" {
  name        = "${local.prefix}-valkey"
  description = "ClearLedger Valkey"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Valkey from ECS"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.prefix}-valkey" })
}
EOF

cd /workspace/submission/infra
cat > kms.tf <<'EOF'
locals {
  kms_usages = toset(["database", "messaging", "projection", "audit"])
}

resource "aws_kms_key" "this" {
  for_each                = local.kms_usages
  description             = "ClearLedger ${each.key} key (${local.prefix})"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  is_enabled              = true
  tags = merge(local.tags, {
    Name                = "${local.prefix}-${each.key}"
    ClearLedgerKeyUsage = each.key
  })
}

resource "aws_kms_alias" "this" {
  for_each      = local.kms_usages
  name          = "alias/${local.prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}

resource "aws_cloudwatch_log_group" "api" {
  name              = local.api_log_group_name
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_cloudwatch_log_group" "projector" {
  name              = local.projector_log_group_name
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_cloudwatch_log_group" "relay" {
  name              = local.relay_log_group_name
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_cloudwatch_log_group" "archiver" {
  name              = local.archiver_log_group_name
  retention_in_days = 14
  tags              = local.tags
}
EOF
cat > data.tf <<'EOF'
# ---------------- RDS PostgreSQL ----------------

resource "aws_db_subnet_group" "main" {
  name       = "${local.prefix}-db-subnets"
  subnet_ids = aws_subnet.private[*].id
  tags       = merge(local.tags, { Name = "${local.prefix}-db-subnets" })
}

resource "aws_db_instance" "main" {
  identifier             = "${local.prefix}-postgres"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  db_name                = local.cfg.db_name
  username               = local.cfg.db_username
  password               = local.cfg.db_password
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.this["database"].arn
  publicly_accessible    = false
  skip_final_snapshot    = true
  deletion_protection    = false
  multi_az               = false
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  apply_immediately      = true

  tags = merge(local.tags, { Name = "${local.prefix}-postgres" })

  lifecycle {
    # Never replace the system of record because of credential/version churn.
    ignore_changes = [password, engine_version]
  }
}

# ---------------- DynamoDB projection store ----------------

resource "aws_dynamodb_table" "projections" {
  name         = "${local.prefix}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }
  attribute {
    name = "SK"
    type = "S"
  }
  attribute {
    name = "GSI1PK"
    type = "S"
  }
  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = merge(local.tags, { Name = "${local.prefix}-projections" })
}

# ---------------- ElastiCache Valkey ----------------

resource "aws_elasticache_subnet_group" "valkey" {
  name       = "${local.prefix}-valkey-subnets"
  subnet_ids = aws_subnet.private[*].id
  tags       = merge(local.tags, { Name = "${local.prefix}-valkey-subnets" })
}

resource "aws_elasticache_replication_group" "valkey" {
  replication_group_id       = "${local.prefix}-valkey"
  description                = "ClearLedger projection cache (${local.prefix})"
  engine                     = "valkey"
  engine_version             = "8.0"
  node_type                  = "cache.t4g.micro"
  num_cache_clusters         = 1
  port                       = 6379
  subnet_group_name          = aws_elasticache_subnet_group.valkey.name
  security_group_ids         = [aws_security_group.valkey.id]
  transit_encryption_enabled = false
  at_rest_encryption_enabled = false
  automatic_failover_enabled = false
  apply_immediately          = true
  tags                       = merge(local.tags, { Name = "${local.prefix}-valkey" })
}

# ---------------- S3 audit archive ----------------

resource "aws_s3_bucket" "audit" {
  bucket        = "${local.prefix}-audit-archive"
  force_destroy = true
  tags          = merge(local.tags, { Name = "${local.prefix}-audit-archive" })
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------- SQS ----------------

resource "aws_sqs_queue" "dlq" {
  name                      = "${local.prefix}-events-dlq"
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600
  tags                      = merge(local.tags, { Name = "${local.prefix}-events-dlq" })
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.prefix}-events"
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })
  tags = merge(local.tags, { Name = "${local.prefix}-events" })
}
EOF

cd /workspace/submission/infra
cat > iam.tf <<'EOF'
locals {
  key_arn = { for k, v in aws_kms_key.this : k => v.arn }
  all_key_arns = [
    local.key_arn["database"],
    local.key_arn["messaging"],
    local.key_arn["projection"],
    local.key_arn["audit"],
  ]

  queue_arn  = aws_sqs_queue.main.arn
  dlq_arn    = aws_sqs_queue.dlq.arn
  table_arn  = aws_dynamodb_table.projections.arn
  index_arn  = "${aws_dynamodb_table.projections.arn}/index/AccountIndex"
  bucket_arn = aws_s3_bucket.audit.arn
  bucket_all = "${aws_s3_bucket.audit.arn}/*"
  bucket_obj = "${aws_s3_bucket.audit.arn}/ledger-audit/*"

  # Log group resources: the group itself and its streams, nothing broader.
  lg = {
    api       = [aws_cloudwatch_log_group.api.arn, "${aws_cloudwatch_log_group.api.arn}:*"]
    projector = [aws_cloudwatch_log_group.projector.arn, "${aws_cloudwatch_log_group.projector.arn}:*"]
    relay     = [aws_cloudwatch_log_group.relay.arn, "${aws_cloudwatch_log_group.relay.arn}:*"]
    archiver  = [aws_cloudwatch_log_group.archiver.arn, "${aws_cloudwatch_log_group.archiver.arn}:*"]
  }

  fn_arn_projector = "arn:aws:lambda:${local.region}:${local.account_id}:function:${local.prefix}-projector"
  fn_arn_relay     = "arn:aws:lambda:${local.region}:${local.account_id}:function:${local.prefix}-outbox-relay"
  fn_arn_archiver  = "arn:aws:lambda:${local.region}:${local.account_id}:function:${local.prefix}-audit-archiver"

  log_write_actions = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  log_deny_actions  = ["logs:CreateLogStream", "logs:PutLogEvents"]
  kms_use_actions   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
  kms_deny_use      = ["kms:Decrypt", "kms:GenerateDataKey"]
  ddb_all_actions   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  s3_all_actions    = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
  sqs_all_actions   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]

  # Every role: never allowed to disable / schedule deletion of the CMKs.
  deny_kms_admin = {
    Sid      = "DenyKmsKeyLifecycle"
    Effect   = "Deny"
    Action   = ["kms:DisableKey", "kms:ScheduleKeyDeletion"]
    Resource = local.all_key_arns
  }

  deny_s3_audit = {
    Sid      = "DenyAuditBucketAccess"
    Effect   = "Deny"
    Action   = local.s3_all_actions
    Resource = [local.bucket_arn, local.bucket_all]
  }

  deny_ddb_all = {
    Sid      = "DenyProjectionTableAccess"
    Effect   = "Deny"
    Action   = local.ddb_all_actions
    Resource = [local.table_arn, local.index_arn]
  }

  deny_sqs_all = {
    Sid      = "DenyQueueAccess"
    Effect   = "Deny"
    Action   = local.sqs_all_actions
    Resource = [local.queue_arn, local.dlq_arn]
  }

  policies = {
    ecs_execution = [
      {
        Sid      = "WriteApiLogs"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.lg.api
      },
      local.deny_kms_admin,
      local.deny_sqs_all,
      local.deny_ddb_all,
      local.deny_s3_audit,
      {
        Sid      = "DenyAllKmsUse"
        Effect   = "Deny"
        Action   = local.kms_deny_use
        Resource = local.all_key_arns
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = concat(local.lg.projector, local.lg.relay, local.lg.archiver)
      },
    ]

    ecs_task = [
      {
        Sid      = "PublishEvents"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "ReadProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
        Resource = [local.table_arn, local.index_arn]
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = local.kms_use_actions
        Resource = [local.key_arn["messaging"], local.key_arn["projection"]]
      },
      {
        Sid      = "WriteApiLogs"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.lg.api
      },
      local.deny_kms_admin,
      {
        Sid      = "DenyQueueConsumeAndDlq"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyDlqAccess"
        Effect   = "Deny"
        Action   = local.sqs_all_actions
        Resource = [local.dlq_arn]
      },
